    public static void rotateClockwise(int[][] matrix)  {  
        int rows=matrix.length;  
        int cols=matrix[0].length;  
        // Transpose the array  
        for (int i=0;i<rows;i++)    {  
            for (int j=i;j<cols;j++)   {  
                int temp=matrix[i][j];  
                matrix[i][j]=matrix[j][i];  
                matrix[j][i]=temp;  
            }  
        }  
        // Reverse each row  
        for (int i=0;i<rows;i++)   {  
            int left=0;  
